output_text:
[
  {
    "id": "cart_required_before_shopping",
    "text": "Customers are obliged to take an available cart from the cart bay before proceeding with their shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_cart_bay": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "at_cart_bay",
              "PICKUP_CART"
            ]
          },
          "post": "with_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart"
    }
  },
  {
    "id": "cart_required_for_item_pickup",
    "text": "Customers are forbidden to pick up shelf items unless they currently have a shopping cart.",
    "abstraction": {
      "state_properties": {
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "item_pickup_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "item_pickup_without_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are forbidden to carry selected items by hand rather than placing them in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "return_cart_to_service_desk",
    "text": "After taking a cart, customers are obliged to return it to the service-desk cart return before leaving the store.",
    "abstraction": {
      "state_properties": {
        "service_desk": "at(0,1)",
        "with_cart": "hasCart",
        "cart_at_service_desk": "cartAt(0,1)",
        "without_cart": {
          "not": "hasCart"
        },
        "cart_returned_state": {
          "and": [
            "cart_at_service_desk",
            "without_cart"
          ]
        }
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "at(1,5)"
            ]
          },
          "post": "with_cart"
        },
        "return_cart_to_service_desk": {
          "pre": {
            "and": [
              "service_desk",
              "with_cart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_returned_state"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_service_desk"
    }
  },
  {
    "id": "only_park_cart_at_service_desk",
    "text": "Customers are forbidden to leave a cart anywhere except the service-desk return cell.",
    "abstraction": {
      "state_properties": {
        "service_desk": "at(0,1)",
        "away_from_service_desk": {
          "not": "service_desk"
        }
      },
      "events": {
        "leave_cart_away_from_service": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "away_from_service_desk"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_service"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Customers are forbidden to exit the supermarket while still possessing a shopping cart.",
    "abstraction": {
      "state_properties": {
        "with_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "at_exit",
              "with_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_free_checkout_approach",
    "text": "Customers are forbidden to push carts eastward through the bottom checkout approach aisle.",
    "abstraction": {
      "state_properties": {
        "bottom_checkout_approach": {
          "or": [
            "at(0,5)",
            "at(1,5)",
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)"
          ]
        },
        "with_cart": "hasCart"
      },
      "events": {
        "push_cart_east_in_checkout_approach": {
          "pre": {
            "and": [
              "bottom_checkout_approach",
              "with_cart",
              "E"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "push_cart_east_in_checkout_approach"
    }
  },
  {
    "id": "backtrack_west_after_milk_pickup",
    "text": "After picking up an item at the milk bay, customers are obliged to leave that bay by backtracking west rather than continuing east.",
    "abstraction": {
      "state_properties": {
        "milk_bay": "at(5,2)",
        "west_of_milk_bay": "at(4,2)"
      },
      "events": {
        "pickup_at_milk_bay": {
          "pre": {
            "and": [
              "milk_bay",
              "PICKUP_ITEM"
            ]
          },
          "post": "milk_bay"
        },
        "go_west_from_milk_bay": {
          "pre": {
            "and": [
              "milk_bay",
              "W"
            ]
          },
          "post": "west_of_milk_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_at_milk_bay",
      "discharge": "go_west_from_milk_bay"
    }
  }
]
